def caesar_shift(s: str, k: int) -> str:
    Shift each ASCII letter in s by k positions in the alphabet, wrapping around and preserving case. k may be negative or larger than 26. Leave all other characters unchanged.

canonical_answer:
def caesar_shift(s, k):
    out = []
    for c in s:
        if "a" <= c <= "z":
            out.append(chr((ord(c) - 97 + k) % 26 + 97))
        elif "A" <= c <= "Z":
            out.append(chr((ord(c) - 65 + k) % 26 + 65))
        else:
            out.append(c)
    return "".join(out)

