def next_permutation(nums: list[int]) -> list[int]:
    Return a new list holding the next lexicographically greater permutation of nums. If nums is already the greatest permutation, return the smallest one (ascending order). Do not modify the input.

canonical_answer:
def next_permutation(nums):
    a = nums[:]
    i = len(a) - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i >= 0:
        j = len(a) - 1
        while a[j] <= a[i]:
            j -= 1
        a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])
    return a

