def edit_distance(a: str, b: str) -> int:
    Return the Levenshtein distance between a and b: the minimum number of single-character insertions, deletions, and substitutions needed to turn a into b.

canonical_answer:
def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]

prompt:
Write a Python function that meets the following specification. Use only the Python standard library.

def dijkstra(n: int, edges: list[tuple[int, int, int]], src: int) -> list[int]:
    Nodes are numbered 0..n-1. edges holds directed edges (u, v, w) with non-negative weight w. Return a list of the shortest distances from src to every node, using -1 for unreachable nodes.

canonical_answer:
import heapq
def dijkstra(n, edges, src):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))
    dist = [None] * n
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if dist[u] is not None:
            continue
        dist[u] = d
        for v, w in adj[u]:
            if dist[v] is None:
                heapq.heappush(pq, (d + w, v))
    return [-1 if d is None else d for d in dist]

