def min_window(s: str, t: str) -> str:
    Return the shortest contiguous substring of s that contains every character of t, including repeated characters at least as many times as they appear in t. If several qualify, return the leftmost. Return '' if none exists or t is empty.

canonical_answer:
from collections import Counter
def min_window(s, t):
    if not t:
        return ""
    need = Counter(t)
    missing = len(t)
    best = (float("inf"), 0, 0)
    l = 0
    for r, c in enumerate(s, 1):
        if need[c] > 0:
            missing -= 1
        need[c] -= 1
        if missing == 0:
            while need[s[l]] < 0:
                need[s[l]] += 1; l += 1
            if r - l < best[0]:
                best = (r - l, l, r)
            need[s[l]] += 1; missing += 1; l += 1
    return "" if best[0] == float("inf") else s[best[1]:best[2]]

