def trapped_water(heights: list[int]) -> int:
    heights gives the heights of adjacent bars of width 1. Return the total units of rainwater trapped between the bars after rain.

canonical_answer:
def trapped_water(heights):
    l, r = 0, len(heights) - 1
    lm = rm = total = 0
    while l < r:
        if heights[l] < heights[r]:
            lm = max(lm, heights[l]); total += lm - heights[l]; l += 1
        else:
            rm = max(rm, heights[r]); total += rm - heights[r]; r -= 1
    return total

