def largest_rectangle(heights: list[int]) -> int:
    heights gives the heights of adjacent histogram bars of width 1. Return the area of the largest rectangle that fits entirely within the histogram. The solution must run in O(n) time.

canonical_answer:
def largest_rectangle(heights):
    st, best = [], 0
    for i, h in enumerate(heights + [0]):
        start = i
        while st and st[-1][1] >= h:
            j, hh = st.pop()
            best = max(best, hh * (i - j))
            start = j
        st.append((start, h))
    return best

